alter table public.timeline_daw_normalization_render_jobs add column if not exists source_byte_length bigint check(source_byte_length>=0);
alter table public.timeline_daw_normalization_master_proofs add column if not exists byte_length bigint check(byte_length>=0);
alter table public.timeline_daw_normalization_alerts add column if not exists condition_key text;
create unique index if not exists timeline_daw_normalization_alert_condition on public.timeline_daw_normalization_alerts(owner_id,session_id,condition_key) where condition_key is not null and state<>'resolved';
alter table public.timeline_daw_normalization_retention_receipts add column if not exists verification_state text not null default 'unverified' check(verification_state in('unverified','verified','partial-failure')),add column if not exists verification_failures jsonb not null default '[]'::jsonb,add column if not exists deleted_byte_length bigint not null default 0;
create table if not exists public.timeline_daw_normalization_lease_history(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,job_id text not null,attempt integer not null,lease_owner text,lease_started_at timestamptz not null,lease_expires_at timestamptz,outcome text not null check(outcome in('claimed','completed','failed','expired','cancelled')),created_at timestamptz not null default now());alter table public.timeline_daw_normalization_lease_history enable row level security;create policy timeline_daw_normalization_lease_history_owner on public.timeline_daw_normalization_lease_history for select to authenticated using(owner_id=auth.uid());